    private fun symbol(name: String, d: String): ImageVector =
        ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f).apply {
            // Symbols use a 0,-960 960x960 viewBox: shift down to the origin.
            group(translationY = 960f) {
                addPath(pathData = PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
            }
        }.build()
}
